export { anatomy, parts, type TogglePart } from "./toggle.anatomy";
export { connect } from "./toggle.connect";
export { getIndicatorId, getRootEl, getRootId } from "./toggle.dom";
export { machine } from "./toggle.machine";
export type {
  ResolvedToggleMachineProps,
  ToggleApi,
  ToggleMachineProps,
  TogglePressedChangeDetails,
  ToggleSchema,
} from "./toggle.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type TogglePart = "root" | "indicator";

export const anatomy: Anatomy<TogglePart> = createAnatomy("toggle").parts("root", "indicator");

export const parts: Record<TogglePart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server. Every handler checks `defaultPrevented`
 * first, which is what makes a consumer's own handler able to veto the machine
 * (merged ahead of ours by `mergeProps`).
 */

import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./toggle.anatomy";
import { getIndicatorId, getRootId } from "./toggle.dom";
import type { ToggleApi, ToggleSchema } from "./toggle.types";

export function connect<T extends PropTypes>(
  service: Service<ToggleSchema>,
  normalize: NormalizeProps<T>,
): ToggleApi<T> {
  const { context, prop, state, send, scope } = service;

  const pressed = context.get("pressed");
  const disabled = prop("disabled");
  // Gated on the state as well as on the value: the source is cleared on the way
  // out of `focused`, but reading both keeps the two from ever disagreeing.
  const focusSource = state.matches("focused") ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  return {
    pressed,
    disabled,
    focusSource,
    focusVisible,

    setPressed(next: boolean): void {
      send({ type: "PRESSED.SET", pressed: next });
    },
    toggle(): void {
      send({ type: "TRIGGER.CLICK" });
    },

    getRootProps: (): T["button"] =>
      normalize.button({
        ...parts.root.attrs,
        id: getRootId(scope),
        type: "button",
        dir: prop("dir"),
        // Native `disabled` rather than `aria-disabled`: a toggle button is not
        // a menu item, it has no reason to stay focusable while inert.
        disabled,
        "aria-pressed": boolAttr(pressed),
        "data-state": pressed ? "on" : "off",
        "data-disabled": dataAttr(disabled),
        "data-focus-visible": dataAttr(focusVisible),
        "data-focus-source": focusSource ?? undefined,
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.BLUR" });
        },
      }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        // The root already carries the state; the indicator is decoration.
        "aria-hidden": ariaAttr(true),
        "data-state": pressed ? "on" : "off",
        "data-disabled": dataAttr(disabled),
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "toggle";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * The smallest complete component, and the one that proves the engine end to end:
 * resolved props, a controlled/uncontrolled bindable, guarded transitions, a state
 * with its own exit action, and a machine-level effect with a teardown.
 *
 * The value lives in `context`, not in the state name. States model interaction
 * modes — idle, focused — while `pressed` is data; folding data into state names
 * is what turns a three-state machine into a twelve-state one as soon as a second
 * flag appears.
 *
 * The modality tracker is installed for the whole life of the service rather than
 * on focus: by the time a focus event arrives, the keydown that caused it has
 * already been and gone, and a tracker started at that moment would report the
 * wrong modality for the very first Tab. It is read once, when focus lands, and
 * the answer is held until focus leaves — see `focusSource` in the schema.
 */

import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import type { ToggleSchema } from "./toggle.types";

export const machine: Machine<ToggleSchema> = createMachine<ToggleSchema>({
  props({ props }) {
    return { disabled: false, ...props };
  },

  context({ prop, bindable }) {
    return {
      pressed: bindable<boolean>(() => ({
        defaultValue: prop("defaultPressed") ?? false,
        value: prop("pressed"),
        onChange: (pressed) => prop("onPressedChange")?.({ pressed }),
        debugLabel: "toggle pressed",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality"],

  // Activation is state-independent: a click lands the same way whether or not
  // the control happens to be focused.
  on: {
    "TRIGGER.CLICK": { guard: "!isDisabled", actions: ["togglePressed"] },
    "PRESSED.SET": { guard: "!isDisabled", actions: ["setPressed"] },
    "ROOT.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource"],
      on: { "ROOT.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      isDisabled: ({ prop }) => prop("disabled"),
    },

    actions: {
      togglePressed({ context }) {
        context.set("pressed", (pressed) => !pressed);
      },
      setPressed({ context, event }) {
        if (event.type === "PRESSED.SET") context.set("pressed", event.pressed);
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
    },

    effects: {
      // No listener: the source is read once at focus, so a modality change no
      // longer has to reach every mounted control. Holding the handle is the
      // whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

export interface TogglePressedChangeDetails {
  readonly pressed: boolean;
}

export interface ToggleMachineProps {
  readonly dir?: Direction | undefined;
  /** Controlled: present means the consumer owns the value. */
  readonly pressed?: boolean | undefined;
  readonly defaultPressed?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  readonly onPressedChange?: ((details: TogglePressedChangeDetails) => void) | undefined;
}

/** What the machine sees once the defaults are applied. */
export interface ResolvedToggleMachineProps extends ToggleMachineProps {
  readonly disabled: boolean;
}

export interface ToggleSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedToggleMachineProps;
  /**
   * `focusSource` is the modality focus arrived under, held until focus leaves.
   * Not the modality of *now*: that one flips to pointer after 300ms of mouse
   * movement whether or not the focus moved, and a ring that blinks out from
   * under a keyboard user's hands is the bug it caused.
   */
  context: { pressed: boolean; focusSource: InputModality | null };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "PRESSED.SET"; pressed: boolean }
    | { type: "ROOT.FOCUS" }
    | { type: "ROOT.BLUR" };
  action: "togglePressed" | "setPressed" | "captureFocusSource" | "clearFocusSource";
  guard: "isDisabled";
  effect: "trackModality";
}

export interface ToggleApi<T extends PropTypes = PropTypes> {
  readonly pressed: boolean;
  readonly disabled: boolean;
  /** The modality focus arrived under, or `null` while the control is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  setPressed(pressed: boolean): void;
  toggle(): void;
  getRootProps(): T["button"];
  getIndicatorProps(): T["element"];
}

/**
 * `<Toggle>` — the same fork as `<Button>`, one part shorter: a root and a single
 * indicator, no loading state and no accessory. `children` and `icon` both land in
 * `ToggleIndicator`, in that order, because the indicator is the only part this
 * machine has to name itself with — a toggle with an icon and no `aria-label` is
 * still nameless, exactly as `IconOnly` in the stories documents.
 *
 * `render` and `asChild` travel in `rest` untouched, same as `ButtonRoot`.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { ToggleIndicator, ToggleRoot, type UseToggleProps } from "./toggle";

export interface ToggleComposedProps
  extends UseToggleProps,
    Omit<PartProps<"button", UseToggleProps>, "children"> {
  /** The label. Text, and text is the only thing that names a toggle by default. */
  readonly children?: ReactNode;
  /** The glyph — an inline SVG, never a text character. Pair it with `aria-label` alone. */
  readonly icon?: ReactNode;
}

export function Toggle(props: ToggleComposedProps): ReactNode {
  const { children, icon, ...rest } = props;

  return (
    <ToggleRoot {...rest}>
      <ToggleIndicator>
        {icon}
        {children}
      </ToggleIndicator>
    </ToggleRoot>
  );
}

export type { ToggleMachineProps, TogglePressedChangeDetails } from "@standarui/core/toggle";
export { Toggle, type ToggleComposedProps } from "./composed";
export {
  type ToggleApi,
  ToggleIndicator,
  type ToggleIndicatorProps,
  ToggleRoot,
  type ToggleRootProps,
  type UseToggleProps,
  useToggle,
} from "./toggle";

/**
 * The toggle the core shipped in Phase 2, given its adapter. Two parts, one
 * machine, and the same shape as every other T1a component: a root that owns the
 * service and publishes its api, a part that reads it.
 */

import * as toggle from "@standarui/core/toggle";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type ToggleApi = toggle.ToggleApi<ReactPropTypes>;

const ToggleContext = createPartContext<ToggleApi>("Toggle");

export interface UseToggleProps extends toggle.ToggleMachineProps, MachineRuntimeProps {}

export function useToggle(props: UseToggleProps): ToggleApi {
  return toggle.connect(useMachine(toggle.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "pressed",
  "defaultPressed",
  "disabled",
  "onPressedChange",
] as const;

export interface ToggleRootProps extends UseToggleProps, PartProps<"button", UseToggleProps> {}

export function ToggleRoot(props: ToggleRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useToggle(machineProps);

  return (
    <ToggleContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "button",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </ToggleContext.Provider>
  );
}

export type ToggleIndicatorProps = PartProps<"span">;

export function ToggleIndicator(props: ToggleIndicatorProps): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const api = ToggleContext.usePart("ToggleIndicator");

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getIndicatorProps(),
    elementProps,
    children,
  });
}
